#!/usr/bin/env bash
# Noir / UltraHonk positive suite for the integrated Phase-4 circuit.
#
# For every vector in tests/positive/ (generated by
# circom/scripts/build_canonical_fixture.js):
#   nargo execute -> public outputs [C, N] must equal
#   testdata/kat/canonical_fixture.json -> bb prove -> bb verify.
#
# ZKEP_SKIP_BB=1 skips only the bb prove/verify step (for environments that
# cannot download the Barretenberg CRS); the run is then reported as
# INCOMPLETE, never as a full pass.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PKG_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
REPO_ROOT="$(cd "$PKG_ROOT/../.." && pwd)"
PKG="phase4_orchestrator"
FIXTURE="$REPO_ROOT/testdata/kat/canonical_fixture.json"
SKIP_BB="${ZKEP_SKIP_BB:-0}"

echo
echo "==============================================="
echo "Running Positive Suite"
echo "Package : $PKG"
echo "==============================================="

(
    cd "$PKG_ROOT"
    nargo compile
)

for VECTOR in "$PKG_ROOT/tests/positive"/*.toml
do
    NAME="$(basename "$VECTOR" .toml)"

    echo
    echo ">>> $NAME"

    cp "$VECTOR" "$PKG_ROOT/_vector.toml"
    OUT="$(cd "$PKG_ROOT" && nargo execute --prover-name _vector 2>&1)" \
        || { echo "$OUT"; rm -f "$PKG_ROOT/_vector.toml"; exit 1; }
    rm -f "$PKG_ROOT/_vector.toml"

    node -e '
const fx = require(process.argv[1]);
const id = process.argv[2];
const m = process.argv[3].match(/Circuit output: \[([^\]]*)\]/);
if (!m) { console.log("FAIL (no circuit output)"); process.exit(1); }
const hex = (x) => "0x" + BigInt(x.trim()).toString(16).padStart(64, "0");
const [c, n] = m[1].split(",").map(hex);
const e = fx.expected_public_outputs[id];
console.log(`  C=${c} N=${n}`);
if (c !== e.commitment || n !== e.nullifier) {
  console.log(`FAIL (expected C=${e.commitment} N=${e.nullifier})`); process.exit(1);
}
console.log("  public outputs match canonical fixture");
' "$FIXTURE" "$NAME" "$OUT"

    if [ "$SKIP_BB" = "1" ]; then
        echo "  bb prove/verify SKIPPED (ZKEP_SKIP_BB=1)"
        continue
    fi

    (
        cd "$PKG_ROOT"
        bb prove \
            -b target/${PKG}.json \
            -w target/${PKG}.gz \
            --write_vk \
            -o target \
            >/dev/null

        bb verify \
            -k target/vk \
            -p target/proof \
            -i target/public_inputs \
            >/dev/null

        # Tampered public inputs (last byte of each 32-byte public input
        # incremented in turn: current_date, registry_root, C, N in Noir ABI
        # order) must not verify.
        node -e '
const fs = require("fs");
const buf = fs.readFileSync("target/public_inputs");
const n = buf.length / 32;
for (let i = 0; i < n; i++) {
  const t = Buffer.from(buf);
  t[32 * i + 31] = (t[32 * i + 31] + 1) & 0xff;
  fs.writeFileSync(`target/public_inputs.tampered${i}`, t);
}
fs.writeFileSync("target/public_inputs.count", String(n));
'
        COUNT="$(cat target/public_inputs.count)"
        for i in $(seq 0 $((COUNT - 1))); do
            if bb verify -k target/vk -p target/proof \
                -i "target/public_inputs.tampered$i" >/dev/null 2>&1; then
                echo "FAIL (tampered public input $i verified)"
                exit 1
            fi
        done
        echo "  $COUNT tampered public inputs rejected"
    )

    echo "PASS"
done

echo
echo "==============================================="
if [ "$SKIP_BB" = "1" ]; then
    echo "POSITIVE SUITE INCOMPLETE: execution checks passed, bb prove/verify skipped"
else
    echo "ALL POSITIVE TESTS PASSED"
fi
echo "==============================================="
